def find_common_items(list_a: list[int], list_b: list[int]) -> list[int]:
    common = []
    for item in list_a:
        if item in list_b and item not in common:
            common.append(item)
    return common

from sqlalchemy.orm import Session


def count_active_users(db: Session) -> int:
    users = db.query(User).filter(User.active == True).all()
    return len(users)


def count_pending_orders(db: Session) -> int:
    orders = db.query(Order).filter(Order.status == 'pending').all()
    return len(orders)

def build_html_list(items: list[str]) -> str:
    html = '<ul>'
    for item in items:
        html += '<li>' + item + '</li>'
    html += '</ul>'
    return html


def build_report_header(sections: list[str]) -> str:
    header = ''
    for section in sections:
        header += '<h2>' + section + '</h2>'
    return header

def enrich_orders(orders: list[dict], products: list[dict]) -> list[dict]:
    enriched = []
    for order in orders:
        product = next(
            (p for p in products if p['id'] == order['product_id']),
            None,
        )
        enriched.append({**order, 'product_name': product['name'] if product else 'N/A'})
    return enriched

def get_high_spenders(orders: list[dict], threshold: float = 1000.0) -> list[int]:
    customer_ids = {o['customer_id'] for o in orders}
    result = []
    for cid in customer_ids:
        total = sum(o['amount'] for o in orders if o['customer_id'] == cid)
        if total > threshold:
            result.append(cid)
    return result

def get_latest_event(events: list[dict]) -> dict | None:
    if not events:
        return None
    sorted_events = sorted(events, key=lambda e: e['timestamp'], reverse=True)
    return sorted_events[0]


def get_cheapest_item(items: list[dict]) -> dict | None:
    if not items:
        return None
    return sorted(items, key=lambda x: x['price'])[0]
